//
// What the client knows about emoji, in one place.
//
// The phone font has no emoji glyphs whatsoever, so an emoji that reaches it draws an empty box.
// Everything the user sees has to come from bundled artwork (images/emoji, generated by
// tools/gen-emoji.py from Noto Emoji) or from a name in words.
//
// isEmoji() is deliberately the ONLY answer to "is this an emoji" in the whole application. It
// used to be a private helper inside the message model that decided what to delete, while nothing
// decided what to draw; with both jobs to do, two separate notions of the question would let a
// code point be stripped by one and rendered by neither, or worse, be passed through to the font.
#ifndef EMOJITEXT_H
#define EMOJITEXT_H

#include <QList>
#include <QString>

namespace EmojiText
{
    /// A code point the phone font cannot draw and that must therefore never reach it: the emoji
    /// blocks, the stragglers scattered through the symbol blocks, and the joiners and selectors
    /// that hold sequences together.
    bool isEmoji(uint cp);

    /// A modifier that qualifies the emoji before it rather than standing on its own - a variation
    /// selector, a skin tone, a zero-width joiner, a keycap. Folded away silently: a tone becomes
    /// the plain emoji, and the parts of a joined sequence are shown separately.
    bool isModifier(uint cp);

    /// True when there is bundled artwork for this code point.
    bool hasArtwork(uint cp);

    /// "qrc:/emoji/e_<hex>.png", or empty when there is no artwork.
    QString artworkUrl(uint cp);

    /// A readable name such as "thumbs up", or empty when the code point is not in the table.
    QString name(uint cp);

    /// True when `text` holds at least one emoji and nothing else but emoji, modifiers and
    /// whitespace. Such a message has no body at all once the emoji are taken out, which is why
    /// it is worth knowing about: it gets names in words instead of arriving blank.
    bool isOnlyEmoji(const QString &text);

    /// `text` with every emoji replaced by its name in square brackets - "[thumbs up]" - and
    /// anything unnamed by "[emoji]". Whitespace is preserved; modifiers are dropped.
    QString toNames(const QString &text);

    /// The shortcode that stands for this emoji while a message is being composed, such as
    /// :thumbs_up:, or empty when there is no artwork for it.
    ///
    /// Composing needs shortcodes because the composer is a plain text field drawn in the phone
    /// font: putting a real emoji into it would show the user an empty box, and an empty box says
    /// nothing about which emoji was picked. The shortcode is turned back into the real character
    /// by fromShortcodes() on the way out, so what is SENT is a normal emoji that every other
    /// client understands.
    QString shortcodeFor(uint cp);

    /// `text` with every :known_shortcode: turned back into its emoji character. Only exact
    /// matches for names in the table are touched, so an ordinary colon, a time like 10:30 or a
    /// URL is left exactly as it was.
    QString fromShortcodes(const QString &text);

    /// Every code point there is artwork for, in the order the picker should offer them.
    ///
    /// NOT code-point order, which is what the generated table is in: that buries the classic
    /// yellow smileys nine rows down behind check marks, stars, hands and hearts, so the emoji
    /// people reach for most are the ones they have to scroll for. Faces lead, then gestures,
    /// then hearts, then the rest; within each band the Unicode order is kept, because it is
    /// what keeps related faces next to each other.
    QList<uint> paletteOrder();

    /// Steps over one code point in `text` at `i`, returning it and advancing `i` past the
    /// surrogate pair if there is one. Shared so that every walk over a message agrees about
    /// where the code points are.
    uint codePointAt(const QString &text, int &i);
}

#endif
